                heading: "Idea generation systems (repeatable)",
                image: "https://images.unsplash.com/photo-1499750310107-5fef28a66643?w=900&q=85",
                body: "Four reliable idea sources:\n1. Audience questions — comments, DMs, competitor post questions\n2. Competitor analysis — what's performing + what angle they haven't covered\n3. Your own experience — mistakes, failures, lessons (unique IP no one can replicate)\n4. Trend injection — trending topic + your niche lens",
