                body: "YouTube's discovery system: CTR (click-through rate) × watch time. CTR = thumbnail + title. Watch time = content delivering the promise the thumbnail made.\n\nTitle tells YouTube what your video is about. CTR tells it whether people want it. Watch time tells it whether people value it. The algorithm distributes to people who watched similar videos.",
