                heading: "Pricing & rate cards",
                body: "CPM-based pricing: average post reach ÷ 1,000 × niche CPM rate.\n\nIndian niche CPMs:\n• Finance/B2B SaaS: ₹2,000–5,000\n• Lifestyle/Fashion: ₹1,200–2,000\n• Entertainment: ₹600–1,000\n\nEngagement rate above 3% justifies a premium multiplier. Publishing rate card publicly: filters low-budget enquiries, signals confidence, anchors negotiations to your number.",
