                body: "Invoice required fields: your legal name + PAN/GSTIN, brand's legal name + GSTIN, deal description (post type, platform, usage rights), amount inclusive of applicable GST, payment terms (due date, bank details), invoice number and date.\n\nSend the invoice the day the contract is signed — not after content delivery. Tools: Zoho Invoice (free tier), QuickBooks, or Google Sheets template.",
